package com.phonepe.columbus.dao.id;

import com.fasterxml.jackson.annotation.JsonTypeName;
import lombok.Data;
import lombok.NonNull;
import lombok.experimental.SuperBuilder;
import lombok.extern.jackson.Jacksonized;

/**
 * Represents an id which is to be automatically generated by the storage.
 */
@Data
@Jacksonized
@SuperBuilder
@JsonTypeName(AutoId.TYPE)
public class AutoId implements Id {

    public static final String TYPE = "AUTO";

    @Override
    public @NonNull String getType() {
        return TYPE;
    }
}
